questions.solutionCode:
function solve(txCountStr, bytesPerTxStr) {
  const txCount = parseInt(txCountStr, 10);
  const bytesPerTx = parseInt(bytesPerTxStr, 10);
  const calldataBytes = txCount * bytesPerTx;
  const blobBytes = 131072;
  const ratio = calldataBytes / blobBytes;
  return JSON.stringify({calldataBytes: String(calldataBytes), blobBytes: String(blobBytes), ratio: ratio.toFixed(2)});
}
